insert into promo_items (id, r, data)
select 'item-10709', 10709, $j${"nm": "Jinx - Loose Cannon (Immersive Arcane Promo)", "se": "OGN", "cn": "251/298", "ra": "", "do": "", "tg": "Promo", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/jinx-loose-cannon-immersive-arcane-promo-ch-item-10709.webp", "inf": "2026 Immersive Arcane Promo, Chinese-language card (OGN 251/298, promo).", "r": 10709, "id": "item-10709", "cat": "PROMO", "la": "Chinese", "ev": "Immersive Arcane Promo", "ty": "Card", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": ""}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10709' or (data->>'nm' = $n$Jinx - Loose Cannon (Immersive Arcane Promo)$n$ and data->>'la' = 'Chinese'));
